import{_ as t,o as n,c as o,a5 as a}from"./chunks/framework.DJo0M80U.js";const g=JSON.parse('{"title":"nginx跨域配置","description":"","frontmatter":{"title":"nginx跨域配置","date":"2026-07-03T00:00:00.000Z","categories":["Java 快速入门"],"tags":["Java","常见需求","OneNote"],"lastUpdated":false},"headers":[],"relativePath":"posts/java快速入门/第十部分：常见需求/nginx跨域配置.md","filePath":"posts/java快速入门/第十部分：常见需求/nginx跨域配置.md"}'),d={name:"posts/java快速入门/第十部分：常见需求/nginx跨域配置.md"};function s(r,e,i,c,l,p){return n(),o("div",null,[...e[0]||(e[0]=[a("<div><p>跨域资源共享（CORS）是一种机制，它使用额外的 HTTP 头来告诉浏览器让运行在一个 origin (域, 协议和端口) 上的 Web 应用被允许访问来自不同源服务器选择的资源。当一个资源从与该资源本身所在的服务器不同的域、协议或端口请求一个资源时，资源会发起一个跨源 HTTP 请求。出于安全考虑，浏览器禁止从跨源 HTTP 请求中读取 Response。这意味着无法使用 XMLHttpRequest 或 Fetch API 从跨源站点请求网页。然而，某些情况下，服务器可以选择接受跨源请求。CORS 是服务器端对跨源请求的一种支持。</p><p>在 Nginx 中，我们可以通过添加一些特定的 HTTP 头来配置 CORS。</p><p>以下是在 Nginx 中配置 CORS 的一般步骤：</p><p>打开你的 Nginx 配置文件。这通常在 /etc/nginx/nginx.conf 或 /etc/nginx/sites-available/default。</p><p>在 server 块内找到你想要进行跨域配置的 location 块。</p><p>在 location 块中添加如下跨域配置：</p><p>nginx Copy code if ($request_method = &#39;OPTIONS&#39;) { add_header &#39;Access-Control-Allow-Origin&#39; &#39;<em>&#39;; add_header &#39;Access-Control-Allow-Methods&#39; &#39;GET, POST, OPTIONS&#39;; add_header &#39;Access-Control-Allow-Headers&#39; &#39;DNT,User-Agent,X-Requested-With,If-Modified-Since,Cache-Control,Content-Type,Range&#39;; add_header &#39;Access-Control-Max-Age&#39; 1728000; add_header &#39;Content-Type&#39; &#39;text/plain; charset=utf-8&#39;; add_header &#39;Content-Length&#39; 0; return 204; } if ($request_method = &#39;POST&#39;) { add_header &#39;Access-Control-Allow-Origin&#39; &#39;</em>&#39;; add_header &#39;Access-Control-Allow-Methods&#39; &#39;GET, POST, OPTIONS&#39;; add_header &#39;Access-Control-Allow-Headers&#39; &#39;DNT,User-Agent,X-Requested-With,If-Modified-Since,Cache-Control,Content-Type,Range&#39;; add_header &#39;Access-Control-Expose-Headers&#39; &#39;Content-Length,Content-Range&#39;; } if ($request_method = &#39;GET&#39;) { add_header &#39;Access-Control-Allow-Origin&#39; &#39;*&#39;; add_header &#39;Access-Control-Allow-Methods&#39; &#39;GET, POST, OPTIONS&#39;; add_header &#39;Access-Control-Allow-Headers&#39; &#39;DNT,User-Agent,X-Requested-With,If-Modified-Since,Cache-Control,Content-Type,Range&#39;; add_header &#39;Access-Control-Expose-Headers&#39; &#39;Content-Length,Content-Range&#39;; } 上述配置允许了所有源的跨域请求，你也可以替换 * 为你需要允许的特定源。</p><p>保存你的 Nginx 配置文件。</p><p>使用 sudo nginx -t 检查你的 Nginx 配置文件是否有语法错误。</p><p>如果没有错误，使用 sudo service nginx reload 或 sudo systemctl reload nginx 重新加载配置文件使更改生效。</p><p>以上就是在 Nginx 中配置 CORS 的一般步骤。如果你有多个 location 块需要配置，只需在每个 location 块中重复以上步骤即可。</p></div>",1)])])}const C=t(d,[["render",s]]);export{g as __pageData,C as default};
